//! Disposable benchmark of existing ObjectModel layout and slot queries.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::{size, Oop};
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap(); let q = h.scope();
    let model = h.named(b"ObjectModel").unwrap();
    let base = h.named(b"ObjectVt").unwrap();
    let gc = h.named(b"GC").unwrap();
    for length in [0, 8] {
        let behavior = q.call(base, b"delegated", &[]).unwrap();
        let kinds = q.call(h.id.root, b"sequence", &vec![size(1).unwrap(); length]).unwrap();
        q.call(model, b"setLayoutOf:to:rest:", &[behavior, kinds, size(1).unwrap()]).unwrap();
        let object = q.call(model, b"allocate:bytes:", &[behavior, size(size_of::<Oop>()).unwrap()]).unwrap();
        let mut parent = behavior;
        let mut objects = Vec::new();
        for _ in 0..16 {
            parent = q.call(parent, b"delegated", &[]).unwrap();
            objects.push(q.call(model, b"allocate:bytes:", &[parent, size(size_of::<Oop>()).unwrap()]).unwrap());
        }
        let cases: &[(&str, &[u8], &[Oop], Oop)] = &[
            ("kind", b"slotKindOf:at:", &[behavior, size(0).unwrap()], size(1).unwrap()),
            ("slot", b"slotAt:in:", &[size(0).unwrap(), object], std::ptr::null_mut()),
            ("inherited", b"slotAt:in:", &[size(0).unwrap(), objects[0]], std::ptr::null_mut()),
            ("deep", b"slotAt:in:", &[size(0).unwrap(), objects[15]], std::ptr::null_mut()),
        ];
        for &(name, selector, args, expected) in cases {
            let selector = q.keep(h.intern(selector).unwrap()).unwrap();
            let calls = 20000;
            for _ in 0..10 { assert_eq!(unsafe { h.id.send(model, selector, args).unwrap() }, expected); }
            for _ in 0..7 {
                q.call(gc, b"collectPrecisely", &[]).unwrap();
                let start = unsafe { clock_gettime_nsec_np(16) };
                for _ in 0..calls { assert_eq!(unsafe { h.id.send(model, selector, args).unwrap() }, expected); }
                println!("{length} {name} {calls} {}", unsafe { clock_gettime_nsec_np(16) } - start);
            }
        }
    }
}

